    const numeric=numbers.has(c.t),date=c.t==='datetime'||c.t==='date';
    const measure=text=>measureColumnText(String(text??''));
    const content=rows.reduce((max,r)=>{const text=String(display(value(r,c.k),c.t,c.decimals));return Math.max(max,...(numeric||date?[text]:text.split(/\s+/)).map(measure))},0);
